247	    private static boolean isLocalAsset(Uri uri) {
248	        String path = uri.getPath();
249	        return "https".equals(uri.getScheme())
250	            && HOST.equals(uri.getHost())
251	            && (uri.getPort() == -1 || uri.getPort() == 443)
252	            && uri.getUserInfo() == null
253	            && path != null
254	            && path.startsWith("/assets/");
255	    }
